insert into public.products (
  brand_id, slug, title_zh_hk, title_zh_cn, title_en,
  description_zh_hk, description_zh_cn, description_en,
  price_hkd, stock, image_paths, status, sort
)
select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"epionce","slug":"hydrating-firming-mask","title_zh_hk":"\u6f64\u6fa4\u7dca\u7dfb\u9762\u819c","title_zh_cn":"\u6da6\u6cfd\u7d27\u81f4\u9762\u819c","title_en":"Hydrating Firming Mask","description_zh_hk":"<p>\u7279\u5f37\u4fdd\u6fd5\u9762\u819c\u5feb\u901f\u4fee\u5fa9\u53ca\u5f37\u5316\u808c\u819a\u4fdd\u8b77\u5c64\uff0c\u63d0\u5347\u808c\u819a\u5f48\u6027\u53ca\u7dca\u7dfb\u5ea6\u3002\u7522\u54c1\u4e2d\u860a\u542b\u9ad8\u6548\u6ecb\u6f64\u808c\u819a\u7684\u795e\u7d93\u905e\u8cea\uff0c\u76ae\u5c64\u8102\u8cea\uff0c\u6297\u6c27\u5316\u690d\u7269\u7cbe\u83ef\u53ca\u5f37\u6548\u4fdd\u6fd5\u5291\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548:</p>\n<p>\u2013 \u9ad8\u6548\u4fdd\u6fd5\u9762\u819c\uff0c\u6fc0\u6d3b\u808c\u819a\u9054\u81f3\u6700\u4f73\u529f\u80fd\u3002</p>\n<p>\u2013 \u860a\u542b\u76ae\u8102\u5316\u5408\u7269\uff0c\u6297\u6c27\u5316\u7269\u53ca\u7279\u5f37\u4fdd\u6fd5\u5291\uff0c\u5feb\u901f\u5f37\u5316\u808c\u819a\u5929\u7136\u4fdd\u8b77\u5c64\u529f\u6548\u3002</p>\n<p>\u2013 \u523a\u6fc0\u7d30\u80de\u88fd\u9020\u4e59\u91af\u81bd\u7d20\uff0c\u5373\u6642\u589e\u5f37\u5f48\u6027\u53ca\u7dca\u7dfb\u5ea6\u3002</p>\n<p>\u2013 \u6291\u5236\u808c\u819a\u88fd\u9020\u7834\u58de\u6027\u708e\u75c7\u56e0\u5b50\uff0c\u4e26\u6e1b\u5c11\u5176\u6d3b\u8e8d\u5ea6\u3002</p>\n\n<p>\u4e3b\u8981\u6210\u5206:</p>\n<p>-\u767d\u67f3\u76ae\u63d0\u53d6\u7269</p>\n<p>\u2013 \u76ae\u5c64\u8102\u8cea\u524d\u9ad4</p>\n<p>\u2013 \u767d\u8292\u82b1</p>\n<p>\u2013 \u4e9e\u9ebb\u5b50\u8907\u5408\u7269</p>","description_zh_cn":"<p>\u7279\u5f3a\u4fdd\u6e7f\u9762\u819c\u5feb\u901f\u4fee\u590d\u53ca\u5f3a\u5316\u808c\u80a4\u4fdd\u62a4\u5c42\uff0c\u63d0\u5347\u808c\u80a4\u5f39\u6027\u53ca\u7d27\u81f4\u5ea6\u3002\u4ea7\u54c1\u4e2d\u8574\u542b\u9ad8\u6548\u6ecb\u6da6\u808c\u80a4\u7684\u795e\u7ecf\u9012\u8d28\uff0c\u76ae\u5c42\u8102\u8d28\uff0c\u6297\u6c27\u5316\u690d\u7269\u7cbe\u534e\u53ca\u5f3a\u6548\u4fdd\u6e7f\u5242\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548:</p>\n<p>\u2013 \u9ad8\u6548\u4fdd\u6e7f\u9762\u819c\uff0c\u6fc0\u6d3b\u808c\u80a4\u8fbe\u81f3\u6700\u4f73\u529f\u80fd\u3002</p>\n<p>\u2013 \u8574\u542b\u76ae\u8102\u5316\u5408\u7269\uff0c\u6297\u6c27\u5316\u7269\u53ca\u7279\u5f3a\u4fdd\u6e7f\u5242\uff0c\u5feb\u901f\u5f3a\u5316\u808c\u80a4\u5929\u7136\u4fdd\u62a4\u5c42\u529f\u6548\u3002</p>\n<p>\u2013 \u523a\u6fc0\u7ec6\u80de\u5236\u9020\u4e59\u91af\u80c6\u7d20\uff0c\u5373\u65f6\u589e\u5f3a\u5f39\u6027\u53ca\u7d27\u81f4\u5ea6\u3002</p>\n<p>\u2013 \u6291\u5236\u808c\u80a4\u5236\u9020\u7834\u574f\u6027\u708e\u75c7\u56e0\u5b50\uff0c\u5e76\u51cf\u5c11\u5176\u6d3b\u8dc3\u5ea6\u3002</p>\n\n<p>\u4e3b\u8981\u6210\u5206:</p>\n<p>-\u767d\u67f3\u76ae\u63d0\u53d6\u7269</p>\n<p>\u2013 \u76ae\u5c42\u8102\u8d28\u524d\u4f53</p>\n<p>\u2013 \u767d\u8292\u82b1</p>\n<p>\u2013 \u4e9a\u9ebb\u5b50\u590d\u5408\u7269</p>","description_en":"<p>An intensive hydrating mask that helps restore and strengthen the skin barrier, improving elasticity and firmness. Contains neurotransmitters, epidermal lipids, antioxidant botanicals and humectants.</p>\n<p>Key benefits</p>\n<p>\u2013 Activates skin for optimal function</p>\n<p>\u2013 Lipids, antioxidants and humectants to reinforce the natural barrier</p>\n<p>\u2013 Stimulates acetylcholine for instant elasticity and firmness</p>\n<p>\u2013 Helps inhibit destructive inflammatory factors</p>\n<p>Key ingredients</p>\n<p>\u2013 White willow bark extract</p>\n<p>\u2013 Epidermal lipid precursors</p>\n<p>\u2013 Meadowfoam</p>\n<p>\u2013 Flaxseed complex</p>","price_hkd":395,"stock":20,"image_paths":["/images/products/prod-12@2x.jpg"],"sort":218}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
  description_zh_hk text, description_zh_cn text, description_en text,
  price_hkd numeric, stock int, image_paths jsonb, sort int
)
join public.brands b on b.slug = x.brand_slug;